// GET ?e_sorder_id=S2737687.0001. Quotes hang off the generation's HubSpot
// deal (one deal per generation), so the gen suffix is required.
const q = $input.first().json.query || {};
const m = String(q.e_sorder_id || '').trim().toUpperCase().match(/^S?(\d+)\.(\d{1,4})$/);
if (!m) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing or invalid e_sorder_id (expected S1234567.0001).', step: 'validate' } } }];
return [{ json: { ok: true, e_sorder_id: 'S' + m[1] + '.' + m[2].padStart(4, '0') } }];

// quote_sent_log on the deal: one line per send, oldest first,
// "<ISO time>|<from mailbox>|<requested by>|<quote link>|<to,to>|<subtotal>".
// Parsed newest first; lines that don't fit are skipped.
const parseLog = (s) => String(s || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l) => {
  const f = l.split('|');
  if (f.length < 5 || !f[0]) return null;
  // Subtotal (6th field) since 2026-10-30; older lines have none (null).
  const sub = f.length > 5 && f[5] !== '' && isFinite(Number(f[5])) ? Number(f[5]) : null;
  return { at: f[0], from: f[1] || '', requested_by: f[2] || '', link: f[3] || null, to: String(f[4] || '').split(',').filter(Boolean), subtotal: sub };
}).filter(Boolean).reverse();
// ok: true goes on to read the deal's quotes. No deal, or a deal with no
// quotes, is not an error: the answer is "no quote" (the page grays out
// View Quote). Quote ids come from the deal Get's associations
// (associations.quotes.results[].id; HubSpot leaves the key out when empty).
const v = $('Validate').first().json;
const d = $input.first().json || {};
const stop = (statusCode, body) => [{ json: { ok: false, statusCode, body } }];
if (d.error) return stop(502, { success: false, error: 'HubSpot deal lookup failed: ' + d.error + ' ' + JSON.stringify(d.message || '').substring(0, 300), step: 'getDeal' });
if (d.objectFound === false || !d.id) return stop(200, { success: true, e_sorder_id: v.e_sorder_id, hs_deal_id: null, quote: null, quotes: [], sent_log: [] });
const a = (d.associations && d.associations.quotes && d.associations.quotes.results) || [];
const ids = [...new Set(a.map((r) => String(r.id)).filter(Boolean))];
const sentLog = String(((d.properties || {}).quote_sent_log) || '');
if (!ids.length) return stop(200, { success: true, e_sorder_id: v.e_sorder_id, hs_deal_id: String(d.id), quote: null, quotes: [], sent_log: parseLog(sentLog) });
return [{ json: { ok: true, dealId: String(d.id), quoteIds: ids.join(','), sentLog } }];

// quote_sent_log on the deal: one line per send, oldest first,
// "<ISO time>|<from mailbox>|<requested by>|<quote link>|<to,to>|<subtotal>".
// Parsed newest first; lines that don't fit are skipped.
const parseLog = (s) => String(s || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l) => {
  const f = l.split('|');
  if (f.length < 5 || !f[0]) return null;
  // Subtotal (6th field) since 2026-10-30; older lines have none (null).
  const sub = f.length > 5 && f[5] !== '' && isFinite(Number(f[5])) ? Number(f[5]) : null;
  return { at: f[0], from: f[1] || '', requested_by: f[2] || '', link: f[3] || null, to: String(f[4] || '').split(',').filter(Boolean), subtotal: sub };
}).filter(Boolean).reverse();
// The deal's quotes, newest first. quote = the newest one with a public
// link (a draft has none yet), or null; the page opens quote.link.
const v = $('Validate').first().json;
const dealId = $('Check deal').first().json.dealId;
const items = $input.all().map((i) => i.json || {});
const err = items.find((j) => j.error);
if (err) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'HubSpot quote read failed: ' + err.error + ' ' + JSON.stringify(err.message || '').substring(0, 300), step: 'getQuotes' } } }];
// Batch Read allInOne gives { results: [...] }; cope with one record per item too.
const rows = [];
for (const j of items) {
  if (Array.isArray(j.results)) rows.push(...j.results);
  else if (j.id && j.properties) rows.push(j);
}
// HubSpot dates arrive as ISO strings or epoch ms; keep YYYY-MM-DD.
const day = (x) => {
  if (x == null || x === '') return null;
  const d = /^\d+$/.test(String(x)) ? new Date(Number(x)) : new Date(String(x));
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};
const today = new Date().toISOString().slice(0, 10);
const quotes = rows.filter((r) => !r.archived).map((r) => {
  const p = r.properties || {};
  const expires = day(p.hs_expiration_date);
  return {
    id: String(r.id),
    title: p.hs_title || '',
    number: p.hs_quote_number || '',
    status: p.hs_status || '',
    link: p.hs_quote_link || null,
    amount: p.hs_quote_amount != null && p.hs_quote_amount !== '' ? Number(p.hs_quote_amount) : null,
    created: p.hs_createdate || null,
    expires,
    expired: !!expires && expires < today,
  };
}).sort((a, b) => String(b.created || '').localeCompare(String(a.created || '')));
const quote = quotes.find((q) => q.link) || null;
return [{ json: { ok: true, statusCode: 200, body: { success: true, e_sorder_id: v.e_sorder_id, hs_deal_id: dealId, quote, quotes, sent_log: parseLog($('Check deal').first().json.sentLog) } } }];
